// Pure helpers for the Survey display. The coverage path itself is generated by
// js/workers/survey_worker.js (from the old 2D widget, unchanged).

import { insertIndex } from './waypoints.js';

// Where a new vertex goes in a closed polygon: into the closest edge within `tolerance`
// (the closing edge from the last vertex back to the first included), else at the end.
export function insertIndexClosed(polygon, p, tolerance) {
	if (polygon.length < 3)
		return polygon.length;
	const closed = [...polygon, polygon[0]];
	const index = insertIndex(closed, p, tolerance);
	return Math.min(index, polygon.length); // the closing edge inserts after the last vertex
}

// Width of the polygon across survey lines at `angleRad` (as the old widget measured it).
export function transectExtent(polygon, angleRad) {
	const nx = -Math.sin(angleRad), ny = Math.cos(angleRad);
	let min = Infinity, max = -Infinity;
	for (const p of polygon) {
		const c = p.x * nx + p.y * ny;
		if (c < min) min = c;
		if (c > max) max = c;
	}
	const extent = max - min;
	return extent > 0 ? extent : 0;
}

export function countTransects(polygon, angleRad, spacing) {
	const extent = transectExtent(polygon, angleRad);
	if (extent === 0 || !(spacing > 0))
		return 0;
	const lines = Math.ceil((extent - spacing * 0.5) / spacing);
	return lines > 0 ? lines : 0;
}

function roundSpacing(value) {
	if (value >= 100)
		return Math.round(value);
	if (value >= 10)
		return Math.round(value * 10) / 10;
	return Math.round(value * 100) / 100;
}

const MIN_LINES = 5, MAX_LINES = 30, TARGET_LINES = 10;

// A spacing giving about ten lines when the current one gives fewer than 5 or more than 30
// (used once, when a polygon first gets three vertices), as the old widget did.
export function autoSpacing(polygon, angleRad, spacing, crosshatch) {
	const lines = countTransects(polygon, angleRad, spacing)
		+ (crosshatch ? countTransects(polygon, angleRad + Math.PI / 2, spacing) : 0);
	if (lines >= MIN_LINES && lines <= MAX_LINES)
		return spacing;
	const extent = transectExtent(polygon, angleRad);
	if (extent === 0)
		return spacing;
	return Math.max(0.05, roundSpacing(extent / TARGET_LINES));
}

const point = (p) => ({ x: Number(p.x), y: Number(p.y), z: Number.isFinite(Number(p.z)) ? Number(p.z) : 0 });
const valid = (p) => p && Number.isFinite(Number(p.x)) && Number.isFinite(Number(p.y));

// The old 2D widget's saved settings -> this display's properties.
export function fromLegacySurvey(state = {}) {
	const num = (v) => (v !== undefined && Number.isFinite(Number(v)) ? Number(v) : undefined);
	const props = {
		mission_topic: state.topic,
		message_type: state.topic_type,
		frame: state.fixed_frame,
		robot_frame: state.base_link_frame,
		polygon: (Array.isArray(state.polygon) ? state.polygon : []).filter(valid).map(point),
		markers: valid(state.start_marker) && valid(state.end_marker) ? [point(state.start_marker), point(state.end_marker)] : [],
		spacing: num(state.spacing),
		angle: num(state.angle),
		turnaround: num(state.turnaround),
		crosshatch: typeof state.crosshatch === "boolean" ? state.crosshatch : undefined,
		direct_transit: typeof state.direct_transit === "boolean" ? state.direct_transit : undefined,
	};
	return Object.fromEntries(Object.entries(props).filter(([, v]) => v !== undefined));
}
